@web.route("/langdian")
def langdian():
    uploadath = os.path.join(basedir, 'static/uploads')
    xlspath = os.path.join(uploadath, "langdian3.json")
    xlspath2 = os.path.join(uploadath, "langdian4.json")

    # try:
    #     db.session.query(SurfSpot).delete()
    #     db.session.commit()
    # except Exception,e:
    #     print e.message

    f =  open(xlspath, "r")
    arr = json.load(f)
    for dict in  arr:
        if "parentCity" in dict:
            pass
        else:
            dict["parentCity"] = ""
        dict["tide"]  = chiantideconst[dict["cid"]]


    w = open(xlspath2,"w")
    w.write(json.dumps(arr))
    w.close()

    return json.dumps(arr)

@web.route("/surfspot")
def surfspot():
    uploadath = os.path.join(basedir, 'static/downloads')
    xlspath = os.path.join(uploadath, "magicseaweed.json")

    # try:
    #     db.session.query(SurfSpot).delete()
    #     db.session.commit()
    # except Exception,e:
    #     print e.message

    with open(xlspath, "r") as f:
        arr = json.load(f)
        for dict in  arr:
            spotdit =  dict["spot"]
            try:
                sport = SurfSpot(dict = spotdit)
                db.session.add(sport)
                db.session.commit()
            except Exception as e:

                db.session.rollback()


    return "done"

@web.route("/surfspot/json")
def surfspotjson():

    list = []
    try:
        spots = db.session.query(SurfSpot).all()
        for spot in spots:
            dict = spot.surfspotDict()
            list.append(dict)
    except Exception as e:
        print(e)


    return json.dumps(list)


