def wannsurfhref(url):
    # urlstring = request.form.get("url","https://www.wannasurf.com/spot/Asia/China/Yellow_Sea/index.html")

    urlstring = url
    driver = webdriver.Chrome()
    result = []
    driver.get(urlstring)

    try:
        html = driver.page_source
        soup = BeautifulSoup(html, 'lxml')
        div = soup.find("div", attrs={"id": "wanna-tabzonespot-spot"})
        if div is not None:
            try:
                table = div.find("table")
                tbody = table.find("tbody")
                trs = tbody.select("tr")
                for tr in trs:
                    a = tr.find("a")
                    shref = a.attrs["href"]
                    spot =  a.text

                    try:
                        insert = WannaSurf(surfspt=spot,href=shref)
                        db.session.add(insert)
                        db.session.commit()

                    except Exception as e:

                        db.session.rollback()
            except Exception as e:
                print(e)

        tablezone = soup.find("table", attrs={"id": "wanna-table"})

        if tablezone is not  None:

            try:

                thead = tablezone.find("thead")
                th  = thead.find("th").text
                if th.find("Zones")>-1:
                    zonetbody = tablezone.find("tbody")
                    zonetrs = zonetbody.select("tr")
                    for zonetr in zonetrs:
                        zonetd = zonetr.find("td")
                        zonea = zonetd.find("a")

                        href = zonea.attrs["href"]



                        wannsurfhref("https://www.wannasurf.com" + href)
                else:
                    pass
            except Exception as  e:
                print(e)




    except Exception as e:
        print(e)


    time.sleep(2)
    driver.quit()

    return "done"















